#!/usr/bin/env node

/**
 * Git Hooks Installer
 *
 * Purpose: Install pre-commit hooks to enforce test discipline
 * Usage: node scripts/install-git-hooks.js
 *
 * This script creates a pre-commit hook that:
 * 1. Runs smoke tests before allowing commit
 * 2. Blocks commit if tests fail
 * 3. Shows clear error messages
 */

const fs = require('fs');
const path = require('path');

const gitHooksDir = path.join(process.cwd(), '.git', 'hooks');
const preCommitPath = path.join(gitHooksDir, 'pre-commit');

const preCommitScript = `#!/bin/sh
#
# LonicFLex Pre-Commit Hook
# Auto-generated by scripts/install-git-hooks.js
#
# This hook runs smoke tests before allowing commits
# to ensure you never commit broken code
#

echo "🧪 Running smoke tests before commit..."
echo ""

# Run smoke tests
npm run test:smoke --silent

# Capture exit code
TEST_EXIT_CODE=$?

echo ""

if [ $TEST_EXIT_CODE -ne 0 ]; then
    echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    echo "❌ COMMIT BLOCKED - Smoke tests failed"
    echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    echo ""
    echo "Fix the failing tests before committing."
    echo "Or run: npm run test:smoke"
    echo ""
    echo "To bypass (NOT RECOMMENDED): git commit --no-verify"
    echo ""
    exit 1
fi

echo "✅ Smoke tests passed - proceeding with commit"
echo ""

exit 0
`;

function installHooks() {
    console.log('\n🔧 Installing Git Hooks...\n');

    // Check if .git directory exists
    if (!fs.existsSync(gitHooksDir)) {
        console.error('❌ Error: .git/hooks directory not found');
        console.error('   Are you in a git repository?');
        process.exit(1);
    }

    // Check if pre-commit hook already exists
    if (fs.existsSync(preCommitPath)) {
        console.log('⚠️  Pre-commit hook already exists');
        console.log(`   Location: ${preCommitPath}`);

        // Read existing hook
        const existingHook = fs.readFileSync(preCommitPath, 'utf8');

        // Check if it's our hook
        if (existingHook.includes('LonicFLex Pre-Commit Hook')) {
            console.log('✅ Hook is already installed (LonicFLex version)');
            return;
        }

        // Backup existing hook
        const backupPath = preCommitPath + '.backup';
        fs.writeFileSync(backupPath, existingHook);
        console.log(`   Backed up to: ${backupPath}`);
    }

    // Write pre-commit hook
    fs.writeFileSync(preCommitPath, preCommitScript, { mode: 0o755 });

    console.log('✅ Pre-commit hook installed successfully');
    console.log(`   Location: ${preCommitPath}`);
    console.log('\n📋 What this does:');
    console.log('   • Runs smoke tests before every commit');
    console.log('   • Blocks commit if tests fail');
    console.log('   • Takes ~30 seconds per commit');
    console.log('\n🚀 Try it now:');
    console.log('   git add .');
    console.log('   git commit -m "test: verify pre-commit hook works"');
    console.log('\n');
}

// Main execution
if (require.main === module) {
    try {
        installHooks();
    } catch (error) {
        console.error('\n❌ Failed to install git hooks:', error.message);
        process.exit(1);
    }
}

module.exports = { installHooks };